From 5646a8d9638509acf6680f4ca3ba986ce20ef2a9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:58:57 +0100
Subject: [PATCH] placement: place parentless modal windows like dialogs

A modal window without a parent, like a secrets dialog shown by kded,
got the normal placement policy and landed in a corner with Minimal
Overlapping. Place it like a dialog, so it ends up centered instead.

BUG: 456060
---
 src/placement.cpp | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/src/placement.cpp b/src/placement.cpp
index cd13738d51..2cdd0952f5 100644
--- a/src/placement.cpp
+++ b/src/placement.cpp
@@ -46,7 +46,7 @@ std::optional<PlacementCommand> Placement::place(const Window *c, const RectF &a
         return placeOnMainWindow(c, area.toRect()); // on mainwindow, if any, otherwise centered
     } else if (c->isOnScreenDisplay() || c->isNotification() || c->isCriticalNotification()) {
         return placeOnScreenDisplay(c, area.toRect());
-    } else if (c->isTransient() && c->surface()) {
+    } else if ((c->isTransient() || c->isModal()) && c->surface()) {
         return placeDialog(c, area.toRect(), options->placement());
     } else if (c->isPictureInPicture()) {
         return placePictureInPicture(c, area.toRect());
-- 
2.53.0

From 03a210bf22fb6dd720a9253cb151d427b7eb77f6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:58:57 +0100
Subject: [PATCH] kded: mark the secrets dialog as modal

The secrets dialog has no parent window, so on Wayland KWin placed it
like a normal window, in a corner with Minimal Overlapping. Making it
window modal lets Qt flag it as a dialog without blocking any input.

BUG: 456060
---
 kded/secretagent.cpp | 1 +
 1 file changed, 1 insertion(+)

diff --git a/kded/secretagent.cpp b/kded/secretagent.cpp
index 689c0d2da..23c018cdd 100644
--- a/kded/secretagent.cpp
+++ b/kded/secretagent.cpp
@@ -456,6 +456,7 @@ bool SecretAgent::processGetSecrets(QSharedPointer<SecretsRequest> request)
         } else {
             request->dialog = m_dialog;
             request->saveSecretsWithoutReply = !connectionSettings->permissions().isEmpty();
+            m_dialog->setWindowModality(Qt::WindowModal);
             m_dialog->show();
             if (KWindowSystem::isPlatformX11()) {
                 KX11Extras::setState(m_dialog->winId(), NET::KeepAbove);
-- 
2.53.0
